  if(params.get('tab')!=='workroom'||params.get('section')!=='tools'||params.get('tool')!=='publication'||new Set(keys).size!==keys.length)return null;
  const fields=action==='prepare'?(params.has('inboxId')?['inboxId']:['productionId','versionId']):action==='review'?['packageId']:action==='link'?(params.has('packageId')?['packageId']:['entryId']):action==='publish'?['packageId',...(params.has('publicationFormat')?['publicationFormat']:[])]:action==='performance'?['entryId','checkpoint']:action==='register'?[]:null;
  if(!fields||keys.length!==base.length+fields.length||keys.some(key=>![...base,...fields].includes(key))||fields.some(key=>key==='checkpoint'?!['24h','72h'].includes(params.get(key)):key==='publicationFormat'?!['youtube-shorts','youtube-video','instagram-reels'].includes(params.get(key)):key==='entryId'?!/^[0-9a-f]{64}$/i.test(params.get(key)||''):!uuid.test(params.get(key)||'')))return null;
