function pfApplyFocusTarget(){const target=pf.focusTarget;if(!target)return;if(Date.now()>target.until||state.user?.id!==pf.userId||state.tab!=='workroom'||wr.view!=='tools'||makerTools.view!=='publication'){pf.focusTarget=null;return;}if(wr.loading||(typeof overlay!=='undefined'&&overlay?.children?.length))return;const element=document.querySelector(target.selector);if(!element||element.contains?.(document.activeElement))return;if(!pfTargetInView(element))element.scrollIntoView?.({block:'center',behavior:'auto'});element.focus?.({preventScroll:true});}
