const pfOption=(value,label,selected)=>`<option value="${escape(value)}" ${value===selected?'selected':''}>${escape(label)}</option>`;
// 날짜는 한국 시간으로 짧게(MM-DD HH:MM). 「내일」 같은 상대 날짜는 화면이 열린 채 자정을 넘기면 틀리므로 쓰지 않는다.
function pfParts(value){const date=new Date(value);if(!value||!Number.isFinite(date.getTime()))return null;return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',weekday:'short',hourCycle:'h23'}).formatToParts(date).map(part=>[part.type,part.value]));}
