async function pfInboxLoad(){if(!pfInboxVisible()||!pf.data?.inbox?.active||pf.inboxFetching||pf.inboxBusy)return;const guard=pfGuard(),request=++pf.inboxRequest;pf.inboxFetching=true;try{const result=await api('/api/publication-inbox');if(!pfAlive(guard)||request!==pf.inboxRequest)return;pf.data.inbox=result;pf.inboxError='';pfInboxPaint();pfListPaint();}catch(error){if(pfAlive(guard)&&request===pf.inboxRequest){pf.inboxError=error.message;pfInboxPaint();}}finally{if(pfAlive(guard)&&request===pf.inboxRequest){pf.inboxFetching=false;pfInboxSchedule();}}}
