function pfLinkPaint(kind,id){if(!pfLinkVisible(kind,id))return;const host=document.querySelector('[data-pf-link-host="'+kind+':'+id+'"]'),record=pfLinkRecord(kind,id),html=pfLinkContents(kind,id);if(!host||html===record.paint)return;const active=host.contains(document.activeElement)?document.activeElement:null,action=active?.dataset?.pfAction,anchor=!active&&document.activeElement?.closest?.('.maker-tools')?document.activeElement:null,top=anchor?.getBoundingClientRect?.().top,parents=pfInboxScrollParents(anchor),scrollX=window.scrollX,scrollY=window.scrollY;host.innerHTML=html;record.paint=html;if(active)(action?host.querySelector('[data-pf-action="'+action+'"]'):host)?.focus?.({preventScroll:true});for(const saved of parents){saved.node.scrollTop=saved.top;saved.node.scrollLeft=saved.left;}window.scrollTo(scrollX,scrollY);if(anchor&&Number.isFinite(top))for(const saved of parents){const delta=anchor.getBoundingClientRect().top-top;if(Math.abs(delta)<0.5)break;saved.node.scrollTop+=delta;}}
