// 24 · 72시간 숫자 표 — 열은 이 편의 채널별 게시, 줄은 서버 지표 정의. 받은 숫자 · 직접 넣을 칸을 먼저 보이고,
// 그날 오는 창 지표와 채널이 주지 않는 숫자는 아래에 접는다.
function pfNumbers(ep,hours,now=Date.now()){
  if(!ep.posted)return `<p class="mt-note">${hours===24?'올린 뒤 게시 기록을 남기면 24시간 숫자를 자동으로 모아요.':'24시간 다음 72시간 숫자도 자동으로 모아요.'}</p>`;
  const cols=ep.entries.map(entry=>({entry,point:pfPoint(entry,hours)})).filter(col=>col.point);
  if(!cols.length)return '<p class="mt-note">이 시점 기록이 없어요.</p>';
  const windowNotes=hours===72?cols.map(col=>pfWindowNote(col.point)).join(''):'';
  if(cols.every(col=>{const due=pfTime(col.point.dueAt);return due!==null&&due>now;}))return `<p class="mt-note">${hours}시간 숫자는 ${escape(pfWhen(cols.map(col=>col.point.dueAt)))}에 자동으로 모아요.</p>${windowNotes}`;
  const key=ep.key+':'+hours,fill=!!pf.fillAll[key],writeAll=pfWritable()&&pf.data?.performance?.canWrite!==false,editable=col=>writeAll&&col.entry.canEdit!==false;
  const defs=pfDefinitions().filter(def=>cols.some(col=>pfDefApplies(def,col.entry)));
  const rows=defs.map(def=>({def,cells:cols.map(col=>{const cell=pfCell(col.entry,col.point,def,now),due=pfTime(col.point.dueAt);if(fill&&['none','late'].includes(cell.kind)&&due!==null&&due<=now)return {...cell,kind:'input',filled:true};return cell;})}));
  const kinds=row=>row.cells.map(cell=>cell.kind),inputRows=rows.filter(row=>kinds(row).includes('input')),valueRows=rows.filter(row=>!inputRows.includes(row)&&kinds(row).includes('value')),lateRows=rows.filter(row=>!inputRows.includes(row)&&!valueRows.includes(row)&&kinds(row).includes('late')),restRows=rows.filter(row=>![...inputRows,...valueRows,...lateRows].includes(row));
  const head=`<thead><tr><th scope="col">지표</th>${cols.map(col=>`<th class="n" scope="col" data-pf-checkpoint="${escape(col.entry.id+':'+hours)}" tabindex="-1">${mtGlyphs([mtPlatformGlyph(col.entry.platform)])} ${escape(PF_FORMATS[col.entry.publicationFormat]?.label||pfPlatformName(col.entry.platform))}<small>${escape(pfPointLabel(col.entry,col.point,now))}</small></th>`).join('')}</tr></thead>`;
  const cell=(row,index)=>{const value=row.cells[index],col=cols[index],def=row.def,id=pfMetricId(def),label=def.label||id,unit=pfUnit(def.unit);switch(value.kind){
    case 'value':return `<td class="n" data-pf-cell="value">${escape(typeof value.value==='number'?mtNum(value.value):String(value.value))}${def.unit&&def.unit!=='count'?`<span class="pf-unit">${escape(unit)}</span>`:''}${pfCellMark(value.source,col.point)}${pfCmp(value.comparison)}</td>`;
    case 'input':{if(!editable(col))return `<td class="n is-missing" data-pf-cell="input" title="${escape(value.reason||'')}">빈칸</td>`;const draftKey=col.entry.id+':'+hours,draft=pf.manual[draftKey]?.metrics?.[id]??'';return `<td class="n" data-pf-cell="input"><label class="mt-cell-input"><input type="number" min="0" ${def.max!==undefined?`max="${Number(def.max)}"`:''} step="${def.unit==='count'?'1':'any'}" inputmode="${def.unit==='count'?'numeric':'decimal'}" data-pf-metric="${escape(id)}" data-key="${escape(draftKey)}" value="${escape(draft)}" placeholder="직접 넣기" aria-label="${escape(pfPlatformName(col.entry.platform)+' '+hours+'시간 '+label)}"><span>${escape(unit)}</span></label></td>`;}
    case 'late':return `<td class="n" data-pf-cell="late"><span class="mt-late">${escape(pfMonthDay(value.at))}에 와요</span></td>`;
    case 'none':return `<td class="n is-none" data-pf-cell="none" title="${escape(value.reason||'')}">—</td>`;
    case 'collecting':return '<td class="n is-none" data-pf-cell="wait">모으는 중</td>';
    case 'scheduled':return `<td class="n is-none" data-pf-cell="wait">${escape(pfDate(value.at))}</td>`;
    default:return '<td class="n is-none" data-pf-cell="na">—</td>';}};
  const line=row=>`<tr><th scope="row">${escape(row.def.label||pfMetricId(row.def))}</th>${row.cells.map((_,index)=>cell(row,index)).join('')}</tr>`,span=cols.length+1;
  const inputCounts=cols.map((col,index)=>({col,count:inputRows.filter(row=>row.cells[index].kind==='input').length})).filter(item=>item.count&&editable(item.col));
  const body=`${valueRows.length?`<tbody><tr class="mt-group-row"><th colspan="${span}">받은 숫자</th></tr>${valueRows.map(line).join('')}</tbody>`:''}${inputRows.length?`<tbody><tr class="mt-group-row is-input"><th colspan="${span}">직접 넣을 칸 ${inputCounts.length?`<span>${escape(inputCounts.map(item=>pfPlatformName(item.col.entry.platform)+' '+item.count).join(' · '))}</span>`:''}</th></tr>${inputRows.map(line).join('')}</tbody>`:''}`;
  const lateAt=rows.flatMap(row=>row.cells.filter(value=>value.kind==='late').map(value=>value.at))[0],foldParts=[lateRows.length&&lateAt?`${pfMonthDay(lateAt)}에 오는 지표 ${lateRows.length}개`:'',restRows.length?`채널이 주지 않거나 없는 숫자 ${restRows.length}개`:''].filter(Boolean);
  const reasons=new Map();rows.forEach(row=>row.cells.forEach((value,index)=>{if(!['none','late','input'].includes(value.kind)||!value.reason)return;const list=reasons.get(value.reason)||[];list.push(pfPlatformName(cols[index].entry.platform)+' '+(row.def.label||pfMetricId(row.def)));reasons.set(value.reason,list);}));
  const fold=foldParts.length||reasons.size?`<details class="mt-fold pf-more"><summary>${escape(foldParts.length?foldParts.join(' · '):'빈칸 이유')}</summary><div class="pf-fold-body">${lateRows.length||restRows.length?`<div class="mt-scroll"><table class="mt-table pf-numbers-table" data-cols="${cols.length}">${head}<tbody>${[...lateRows,...restRows].map(line).join('')}</tbody></table></div>`:''}${reasons.size?`<ul class="pf-reasons">${[...reasons].map(([reason,list])=>`<li><span>${escape(reason)}</span><b>${escape(list.join(' · '))}</b></li>`).join('')}</ul>`:''}</div></details>`:'';
  const messages=cols.filter(col=>col.point.status!=='recorded'&&(col.point.message||col.point.nextAttemptAt)).map(col=>`<p class="mt-note">${escape(pfPlatformName(col.entry.platform))} · ${escape(col.point.message||'')}${col.point.nextAttemptAt?` 다음 확인 ${escape(pfDate(col.point.nextAttemptAt))}`:''}</p>`).join('');
  const hasNone=rows.some(row=>row.cells.some(value=>value.kind==='none')),hasLate=!!lateAt,hasInput=inputRows.length>0;
  const legend=[hasNone?'「—」는 그 채널이 주지 않는 숫자':'',hasLate?(hours===24?`「${pfMonthDay(lateAt)}에 와요」는 그날 72시간 칸에 자동으로 오는 숫자`:`「${pfMonthDay(lateAt)}에 와요」는 그날 자동으로 오는 숫자`):'',hasInput?'「직접 넣기」는 사람이 넣는 숫자':''].filter(Boolean);
  const canFill=writeAll&&cols.some(editable)&&rows.some(row=>row.cells.some(value=>['none','late'].includes(value.kind)||value.filled));
  const keys=cols.filter(editable).map(col=>col.entry.id+':'+hours),draft=keys.map(key=>pf.manual[key]).find(row=>row?.measuredAt||row?.note)||pf.manual[keys[0]]||{},hasInputs=inputCounts.length>0;
  const save=hasInputs?`<div class="mt-form-row pf-save"><label class="mt-field"><span>본 시각 <small>한국 시간</small></span><input type="datetime-local" data-pf-measured="${escape(keys.join(' '))}" value="${escape(draft.measuredAt||pfLocalNow())}" required><small class="mt-field-help">예전에 본 숫자면 그때 본 시각을 넣어요.</small></label><label class="mt-field is-wide"><span>어디서 봤나요 <small>선택</small></span><input type="text" data-pf-note="${escape(keys.join(' '))}" maxlength="1000" value="${escape(draft.note||'')}" placeholder="${escape([...new Set(cols.map(col=>PF_WHERE[col.entry.platform]||'플랫폼 화면'))].join(' · '))}"></label><button class="btn" type="submit">저장</button></div>`:'';
  const table=`<div class="mt-scroll"><table class="mt-table pf-numbers-table" data-cols="${cols.length}">${head}${body}</table></div>`;
  const legendLine=`<p class="mt-note pf-legend">${escape(legend.length?legend.join(', ')+'예요. ':'')}비어 있어도 0으로 세지 않고, 이미 있는 숫자는 바뀌지 않아요.${canFill?' ':''}${canFill?pfButton(fill?'넣을 칸만 보기':'다른 빈칸도 직접 넣기','fill-all',`data-key="${escape(key)}"`,'small'):''}</p>`;
  return `${windowNotes}${hasInputs?`<form class="pf-numbers" data-pf-form="metrics" data-entries="${escape(cols.filter(editable).map(col=>col.entry.id).join(' '))}" data-hours="${hours}"><fieldset ${pf.busy?'disabled':''}>${table}${save}</fieldset></form>`:`<div class="pf-numbers">${table}</div>`}${legendLine}${fold}${messages}`;
}
// 게시 기록 한 줄(채널 · 게시 시각 · 주소 · 수집 켜고 끄기 · 주소 열림 확인).
function pfEntryCard(entry,write,epTitle){
  const channel=(pf.data?.performance?.channels||[]).find(row=>row.id===entry.channelId),canWrite=write&&entry.canEdit!==false,url=pfReviewLink(entry.url),name=entry.channelName||channel?.displayName||channel?.name||channel?.label||channel?.handle||entry.channelId,format=PF_FORMATS[entry.publicationFormat]?.label,title=epTitle===undefined||pfNorm(entry.title)!==pfNorm(epTitle)?entry.title||'게시한 콘텐츠':'';
  return `<article class="pf-post" data-pf-entry="${escape(entry.id)}"><div class="pf-post-head">${mtGlyphs([mtPlatformGlyph(entry.platform)])}<div><strong>${escape(name)}${format?` · ${escape(format)}`:''}</strong><small>${title?`${escape(title)} · `:''}${escape(pfDay(entry.publishedAt))} ${escape(pfClock(entry.publishedAt))} 게시${entry.origin==='auto'?' · <span data-pf-auto>자동 등록</span>':''}</small></div>${url?`<a class="mt-link" href="${escape(url)}" target="_blank" rel="noopener noreferrer">게시물 열기</a>`:''}</div>${entry.active===false?'<p class="mt-note">자동 수집을 멈췄어요. 다시 켜도 24·72시간 모을 시각은 그대로예요.</p>':''}${entry.comparison?`<p class="mt-note">${escape(typeof entry.comparison==='string'?entry.comparison:entry.comparison.message||entry.comparison.summary||'')}</p>`:''}${canWrite?`<div class="mt-actions">${pfButton('지금 확인','collect',`data-id="${escape(entry.id)}" ${pf.busy||entry.active===false?'disabled':''}`,'small')}${pfButton(entry.active===false?'자동 수집 다시 켜기':'자동 수집 멈추기','active',`data-id="${escape(entry.id)}" ${pf.busy?'disabled':''}`,'small')}</div>`:''}${entry.active!==false?pfLinkHost('post',entry.id):''}</article>`;
}
function pfPosts(ep,write){
  const pack=ep.packages[0],uncovered=ep.posted&&pack?(pack.channels||[]).filter(id=>PF_FORMATS[id]&&!ep.entries.some(entry=>entry.publicationFormat===id||!entry.publicationFormat&&entry.platform===PF_FORMATS[id].platform)):[];
  const rows=ep.entries.map(entry=>pfEntryCard(entry,write&&pf.data?.performance?.canWrite!==false,ep.title)).join('');
  const other=pf.registration?.publicationPackageId&&!ep.packages.some(item=>item.id===pf.registration.publicationPackageId)?'<p class="mt-note">다른 편의 묶음을 고른 게시 기록을 쓰는 중이에요.</p>':'';
  const form=pfRegisterForm(false),openForm=!ep.posted||pf.target?.action==='publish'||!pfRegistrationPristine();
  return `${rows}${uncovered.length?`<p class="mt-note">${escape(uncovered.map(id=>PF_FORMATS[id].label).join(' · '))} 게시 기록이 아직 없어요. 올렸다면 아래에 넣어요.</p>`:''}${ep.posted?`<details class="mt-fold pf-register-fold" data-pf-register-fold${openForm?' open':''}><summary>다른 채널 게시 기록 넣기</summary><div class="pf-fold-body">${other}${form}</div></details>`:`<p class="mt-note">채널에 올린 뒤 게시 주소와 시각을 남기면 24·72시간 숫자를 자동으로 모아요.</p>${other}${form}`}`;
}
function pfRegisterForm(primary){
  const registration=pf.registration,performance=pf.data?.performance||{},write=pfWritable()&&performance.canWrite!==false,channels=performance.channels||[];
  if(!write)return '<p class="mt-note">지금 권한으로는 게시 기록을 읽기만 할 수 있어요.</p>';
  return `<form class="mt-form pf-register" data-pf-form="register"><fieldset ${pf.busy?'disabled':''}><div class="mt-form-row"><label class="mt-field"><span>게시한 계정</span><select data-pf-register="channelId" required>${pfOption('','계정 고르기',registration.channelId)}${channels.map(row=>pfOption(row.id,row.displayName||row.name||row.label||row.handle||row.canonicalUrl||row.id,registration.channelId)).join('')}</select></label><label class="mt-field"><span>게시 시각 <small>한국 시간</small></span><input type="datetime-local" data-pf-register="publishedAt" required value="${escape(registration.publishedAt)}"><small class="mt-field-help" data-pf-register-hint>${escape(pfPublishedHint())}</small></label></div><label class="mt-field"><span>게시 주소</span><input type="url" data-pf-register="url" maxlength="2048" required value="${escape(registration.url)}" placeholder="https://…"></label>${pfLookupAvailable()?`<div class="pf-lookup">${pfButton('주소 확인','lookup',pfLookupBlocked()?'disabled':'','small')}<div class="pf-lookup-note" aria-live="polite">${pfLookupNote()}</div></div>`:''}<div class="mt-form-row"><label class="mt-field is-wide"><span>제목</span><input data-pf-register="title" maxlength="200" value="${escape(registration.title)}"></label><label class="mt-field"><span>게시 묶음 <small>선택</small></span><select data-pf-register="publicationPackageId">${pfOption('','잇지 않음',registration.publicationPackageId)}${pfPackages().map(row=>pfOption(row.id,row.title,registration.publicationPackageId)).join('')}</select></label></div>${pfRegisterFormatHost()}<button class="btn${primary?' primary':''}" type="submit" ${pfRegisterBlocked()?'disabled':''}>게시 기록 저장</button></fieldset></form>${!channels.length?'<p class="mt-note">기록할 계정이 없어요. 내 관리 페이지에서 계정을 연결해 주세요.</p>':''}`;
}
function pfRegisterDetail(model){return `<div class="mt-detail is-form" data-pf-detail="register">${pfMobileStrip(model)}${pfStatusLine()}${pfErrors()}${pfTargetChoicePanel()}<div class="mt-form-head"><div>${mtKicker('NEW RECORD')}<h2>게시 기록 넣기</h2><p>게시 주소와 시각을 남기면 24·72시간에 숫자를 자동으로 모아요. 연결한 계정에 새로 올린 공개 게시물은 24시간 안에 자동으로 기록되기도 해요(페이스북은 영상·릴스만).</p></div><button type="button" class="btn icon" data-pf-action="form-close" aria-label="닫기" title="닫기">${mtIcon('close')}</button></div><section class="mt-step">${pfRegisterForm(true)}</section></div>`;}
function pfPackageCard(row,registerButton=true){const url='/api/publication-packages/'+encodeURIComponent(row.id)+'/download',reviewing=pf.reviewPackageId===row.id,checks=(row.checks||[]).length+(row.outputs||[]).reduce((sum,output)=>sum+(output.checks||[]).length,0);return `<article class="pf-package" tabindex="-1" data-pf-package="${escape(row.id)}"><div class="pf-package-head"><div><strong>${escape(row.title)}</strong><small>${escape(pfDate(row.createdAt))} 만듦 · ${escape(row.source?.fileName||'완성본')}</small></div><div class="mt-actions"><a class="btn small" href="${url}" download>${mtIcon('download')}ZIP 받기</a>${pfButton('게시 전 점검','review-open',`data-id="${escape(row.id)}" ${pf.reviewBusy?'disabled':''}`,'small')}</div></div><div class="pf-package-overview" data-pf-package-overview="${escape(row.id)}" ${reviewing?'hidden':''}><ul class="pf-outputs">${(row.outputs||[]).map(output=>`<li>${mtGlyphs([mtPlatformGlyph(PF_FORMATS[output.channel]?.platform||output.channel)])}<div><strong>${escape(output.label||output.channel)}</strong><small>${escape(output.fileName)} · ${escape(String(output.width))} × ${escape(String(output.height))} · ${(Number(output.byteSize||0)/1048576).toFixed(1)}MiB</small>${output.mediaId?`<details class="pf-output-video"><summary>영상 보기</summary><video class="pf-video" src="/api/studio-media/${encodeURIComponent(output.mediaId)}" controls playsinline preload="none" aria-label="${escape(output.label||output.channel)} 최종 영상"></video></details>`:''}</div></li>`).join('')}</ul>${checks||row.subtitle?`<details class="mt-fold pf-checks-fold"><summary><span>기술 검사 결과 <b>${checks}</b></span></summary><div class="pf-fold-body">${pfChecks(row.checks)}${(row.outputs||[]).map(output=>(output.checks||[]).length?`<h5>${escape(output.label||output.channel)}</h5>${pfChecks(output.checks)}`:'').join('')}${row.subtitle?`<p class="mt-note">자막 ${Number(row.subtitle.cueCount||0)}개 · 오류 ${Number(row.subtitle.errors||0)} · 볼 것 ${Number(row.subtitle.warnings||0)}</p>`:''}</div></details>`:''}</div>${registerButton&&pfWritable()?`<div class="mt-actions">${pfButton('게시 기록 넣기','use-package',`data-id="${escape(row.id)}" ${pf.reviewBusy?'disabled':''}`,'small')}</div>`:''}${pfReviewHost(row.id)}</article>`;}
function pfPackageSection(ep){
  if(ep.packages.length)return `<p class="mt-note">채널마다 영상·게시문·자막·검사 결과를 ZIP으로 받아요. 받은 파일은 직접 보고 올려요.</p>${ep.packages.map(row=>pfPackageCard(row,false)).join('')}`;
  if(ep.inbox||!ep.posted)return `<p class="mt-note">아직 묶음이 없어요. 채널을 고르면 영상·게시문·자막을 채널별로 묶어요.</p>${pfWritable()?pfButton('묶음 만들기','package-new',ep.inbox?`data-inbox="${escape(ep.inbox.id)}"`:'','small'):''}`;
  return '<p class="mt-note">이 편은 게시 묶음 없이 올렸어요.</p>';
}
// 새 게시 묶음 — 상세 자리에 폼이 들어온다(목록은 그대로). 01 완성본 · 02 채널 · 03 글 · 04 자막.
function pfPackageForm(model){
  const draft=pf.draft,production=pf.production,write=pfWritable(),versions=(production?.versions||[]).filter(row=>row.kind==='video'&&row.mediaId),selected=versions.find(row=>row.id===draft.versionId),profiles=pf.data.catalog?.channels||[],limit=draft.channels.includes('instagram-reels')?2200:5000;
  const source=`<label class="mt-field"><span>제작 스튜디오의 완성본</span><select data-pf-source ${pf.busy?'disabled':''}>${pfOption('','새 완성본 올리기',draft.productionId)}${(pf.data.studio?.productions||[]).map(row=>pfOption(row.id,row.title,draft.productionId)).join('')}</select><small class="mt-field-help">새로 올린 영상은 나만 보는 작업으로 시작해요. 기존 작업의 영상은 그 작업의 공개 범위를 따라요.</small></label>${draft.productionId&&!production?'<p class="mt-note" role="status">작업의 파일을 불러오고 있어요.</p>':''}${versions.length?`<label class="mt-field"><span>올릴 영상 버전</span><select data-pf-field="versionId" ${pf.busy?'disabled':''}>${versions.map(row=>pfOption(row.id,row.label||row.fileName,draft.versionId)).join('')}</select></label>`:''}${selected?`<video class="pf-video" src="/api/studio-media/${encodeURIComponent(selected.mediaId)}" controls playsinline preload="metadata" aria-label="고른 완성본"></video><p class="mt-note">${escape(selected.fileName||selected.label)} · 끝까지 틀어 화면과 소리를 봐요.</p>`:''}`;
  const upload=write&&(!production||production.canEdit)?`<form class="pf-upload" data-pf-form="upload"><fieldset ${pf.busy?'disabled':''}>${mtDrop({attrs:'accept="video/mp4,video/webm,.mp4,.webm" data-pf-file',title:pf.file?pf.file.name:versions.length?'새 버전 올리기':'다른 영상 올리기',hint:pf.file?`${(pf.file.size/1048576).toFixed(1)}MiB · 저장을 누르면 올려요`:'끌어다 놓거나 눌러서 고르기 · MP4·WebM · 100MiB까지',set:!!pf.file})}${pf.file?`<button type="submit" class="btn small">${pf.busy?'올리는 중…':'영상 저장'}</button>`:''}</fieldset></form>`:'';
  const channels=`<div class="mt-channels">${profiles.map(profile=>`<label class="mt-channel"><input type="checkbox" data-pf-channel="${escape(profile.id)}" ${draft.channels.includes(profile.id)?'checked':''}><span>${mtGlyphs([mtPlatformGlyph(PF_FORMATS[profile.id]?.platform||profile.id)])}<strong>${escape(profile.label)}</strong><small>${escape(String(profile.width))} × ${escape(String(profile.height))}</small></span></label>`).join('')}</div>`;
  return `<div class="mt-detail is-form" data-pf-detail="form">${pfMobileStrip(model)}${pfStatusLine()}${pfErrors()}${pfTargetChoicePanel()}<div class="mt-form-head"><div>${mtKicker('NEW PACKAGE')}<h2>새 게시 묶음</h2><p>채널마다 영상·게시문·자막·검사 결과를 ZIP으로 받아요. 올리기 전에 직접 한 번 보고 올려요.</p></div><button type="button" class="btn icon" data-pf-action="form-close" aria-label="닫기" title="닫기">${mtIcon('close')}</button></div>
<section class="mt-step"><h3><span class="mt-num">01</span>완성본</h3>${pfInboxPanel()}${source}${upload}</section>
<form class="pf-package-form" data-pf-form="package"><fieldset ${!write||pf.busy?'disabled':''}><section class="mt-step"><h3><span class="mt-num">02</span>채널</h3>${channels}<label class="mt-field"><span>화면 맞추기</span><select data-pf-field="mode">${pfOption('adapt','자르지 않고 채널 크기에 맞추기(여백)',draft.mode)}${pfOption('original','규격이 맞는 원본 그대로',draft.mode)}</select><small class="mt-field-help">비율이 다르면 여백을 넣어요. 원본은 그대로 둬요.</small></label>${pf.data.catalog?.capabilities?.conversion===false?'<p class="mt-note">이 서버에는 영상 변환 도구가 없어요. 규격이 맞는 원본만 묶을 수 있어요.</p>':''}</section>
<section class="mt-step"><h3><span class="mt-num">03</span>글</h3><label class="mt-field"><span>제목</span><input data-pf-field="title" maxlength="100" required value="${escape(draft.title)}" placeholder="이번 편 제목"></label><label class="mt-field"><span>게시문 <small><span data-pf-count="body">${mtNum(draft.body.length)}</span> / ${mtNum(limit)}</small></span><textarea data-pf-field="body" rows="5" maxlength="${limit}" placeholder="채널별 게시문 파일에 담을 글">${escape(draft.body)}</textarea><small class="mt-field-help">인스타그램을 고르면 2,200자, 아니면 5,000자까지예요.</small></label><div class="mt-form-row"><label class="mt-field is-wide"><span>연결할 주소 <small>선택</small></span><input type="url" data-pf-field="link" maxlength="2048" value="${escape(draft.link)}" placeholder="https://synk.im/…"></label><label class="mt-field"><span>언어</span><input data-pf-field="language" maxlength="20" required value="${escape(draft.language)}" placeholder="ko"></label></div></section>
<section class="mt-step"><h3><span class="mt-num">04</span>자막 <small>선택</small></h3>${mtDrop({attrs:'accept=".srt,.vtt,text/vtt" data-pf-subtitle',title:draft.subtitleFileName||'SRT·VTT 자막 놓기',hint:draft.subtitleText?'넣은 자막은 묶기 전에 시간·빈 줄을 검사해요':'넣으면 묶기 전에 시간·빈 줄을 검사해요 · 영상에 구운 자막이면 비워 둬요',icon:'file',small:true,set:!!draft.subtitleText})}<details class="mt-fold pf-subtitles"${draft.subtitleText?' open':''}><summary>자막 글 보기·고치기</summary><div class="pf-fold-body"><label class="mt-field"><span>자막 내용</span><textarea data-pf-field="subtitleText" rows="5" maxlength="200000">${escape(draft.subtitleText)}</textarea></label>${draft.subtitleText?pfButton('자막 비우기','clear-subtitle','','small'):''}</div></details></section>
<div class="mt-form-foot">${!selected?`<span class="mt-note">${draft.productionId&&production&&!versions.length?'이 완성본에는 올릴 영상이 없어요. 영상을 올리면 만들 수 있어요':'완성본을 고르면 만들 수 있어요'}</span>`:''}<button type="button" class="btn" data-pf-action="form-close">취소</button><button type="submit" class="btn primary" ${!selected?'disabled':''}>${pf.busy?'묶음 만드는 중…':'묶음 만들기'}</button></div></fieldset></form></div>`;
}

// ── 고르기 · 거르기 · 열기 ──
function pfPick(key){const episodes=pfEpisodes();if(!episodes.some(ep=>ep.key===key))return;pf.pick=key;pf.picking=false;pf.form='';pf.target=null;pfSyncView();pfRenderKeep();queueMicrotask(pfScrollDetail);}
function pfScrollDetail(){const detail=pfQuery('.maker-tools[data-mt="publication"] .mt-detail'),rect=detail?.getBoundingClientRect?.();if(rect&&rect.top<0)detail.scrollIntoView?.({block:'start'});}
// 번호 구역을 펼치고, 다시 그린 뒤 처음 맞는 자리(입력 칸 → 구역 머리)에 초점을 둔다.
function pfOpenSec(num,...focus){const ep=pfCurrentEpisode();if(!ep)return;pf.form='';pf.secOpen[ep.key+':'+num]=true;pfSyncView();pfRender();pfFocusTarget([...focus,`[data-pf-sec="${num}"]>summary`].find(selector=>pfQuery(selector))||`[data-pf-sec="${num}"]>summary`);}
function pfOpenForm(inboxId){if(!pfWritable())return;pf.form='package';pf.picking=false;pf.target=null;pfSyncView();pfRender();if(inboxId)void pfInboxUse(inboxId);queueMicrotask(pfScrollDetail);}
function pfCloseForm(){pf.form='';pf.inboxChoice='';pfSyncView();pfRender();}

// ── 저장 · 올리기 · 기록 ──
async function pfSelectProduction(id){if(pf.busy)return;pf.draft.productionId=id;pf.draft.versionId='';pf.production=null;pf.file=null;pf.error='';const guard=pfGuard(),request=++pf.detailRequest;pfRender();if(!id)return;try{const result=await api('/api/studio-productions/'+encodeURIComponent(id));if(!pfAlive(guard)||request!==pf.detailRequest||pf.draft.productionId!==id)return;pf.production=result.production;const version=[...(result.production.versions||[])].reverse().find(row=>row.kind==='video'&&row.mediaId);pf.draft.versionId=version?.id||'';if(!pf.draft.title)pf.draft.title=result.production.title;}catch(error){if(pfAlive(guard)&&request===pf.detailRequest)pf.error=error.message;}finally{if(pfAlive(guard)&&request===pf.detailRequest)pfRender();}}
function pfSetStatus(message){pf.status=message;const element=document.querySelector('[data-pf-status]');if(element)element.textContent=message;}
function pfUpload(id,file,guard){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();pf.upload=xhr;xhr.open('POST','/api/studio-productions/'+encodeURIComponent(id)+'/media');xhr.withCredentials=true;xhr.timeout=180000;xhr.setRequestHeader('Content-Type',file.type||(/\.webm$/i.test(file.name)?'video/webm':'video/mp4'));xhr.setRequestHeader('X-CSRF-Token',state.csrf);xhr.setRequestHeader('X-File-Name',encodeURIComponent(file.name));xhr.setRequestHeader('X-Version-Label',encodeURIComponent('완성본 · '+file.name.slice(0,85)));xhr.upload.onprogress=event=>{if(pfAlive(guard)&&event.lengthComputable)pfSetStatus('완성본 올리는 중 '+Math.round(event.loaded/event.total*100)+'%');};xhr.onload=()=>{if(pf.upload===xhr)pf.upload=null;let data;try{data=JSON.parse(xhr.responseText);}catch{return reject(new Error('저장 응답을 읽지 못했어요. 새로고침해서 저장됐는지 봐 주세요.'));}if(xhr.status<200||xhr.status>=300)return reject(new Error(data.error||data.message||'파일을 저장하지 못했어요.'));resolve(data);};xhr.onerror=xhr.ontimeout=()=>{if(pf.upload===xhr)pf.upload=null;reject(new Error('파일을 올리지 못했어요. 인터넷 연결과 파일 크기를 보고 다시 올려 주세요.'));};xhr.onabort=()=>reject(new Error('파일 올리기를 취소했어요.'));xhr.send(file);});}
async function pfUploadSelected(){if(pf.busy||!pfWritable()||!pf.file)return;const file=pf.file,guard=pfGuard();pf.busy=true;pf.error='';pfSetStatus('완성본을 저장하고 있어요.');pfRender();try{if(file.size<1||file.size>104857600||!(/\.(mp4|webm)$/i.test(file.name)))throw new Error('MP4·WebM 영상을 100MiB 이하로 골라 주세요.');let id=pf.draft.productionId;if(!id){const result=await api('/api/studio-productions',{title:pf.draft.title.trim()||file.name,stage:'ready'});if(!pfAlive(guard))return;pf.production=result.production;id=result.production.id;pf.draft.productionId=id;if(!pf.draft.title)pf.draft.title=result.production.title;pf.data.studio.productions=[result.production,...pf.data.studio.productions.filter(row=>row.id!==id)];}const result=await pfUpload(id,file,guard);if(!pfAlive(guard))return;pf.production=result.production;const version=[...(result.production.versions||[])].reverse().find(row=>row.kind==='video'&&row.mediaId);pf.draft.versionId=version?.id||'';pf.file=null;pfSetStatus('완성본을 저장했어요. 채널을 골라 주세요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('');}}finally{if(pfAlive(guard)){pf.busy=false;pfRender();}}}
async function pfCreatePackage(){if(pf.busy||!pfWritable())return;const guard=pfGuard(),payload=structuredClone(pf.draft);if(!payload.productionId||!payload.versionId){pf.error='완성본을 먼저 골라 주세요.';pfRender();return;}pf.busy=true;pf.error='';pfSetStatus('채널별 영상과 게시문을 만들고 있어요. 영상이 길면 시간이 걸려요.');pfRender();try{const result=await api('/api/publication-packages',payload);if(!pfAlive(guard))return;pf.data.packages.packages=[result.package,...pfPackages().filter(row=>row.id!==result.package.id)];const key=result.package?.productionId&&result.package?.versionId?'v:'+result.package.productionId+':'+result.package.versionId:'p:'+result.package?.id;pf.form='';pf.pick=key;pf.secOpen[key+':04']=true;pfSetStatus('게시 묶음을 만들었어요. ZIP을 받아 채널별 영상을 끝까지 틀어 봐요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('쓴 내용은 그대로 있어요.');}}finally{if(pfAlive(guard)){pf.busy=false;pfSyncView();pfRender();}}}
async function pfRegisterPost(){if(pf.busy||!pfWritable()||pf.data?.performance?.canWrite===false)return;const guard=pfGuard(),input=structuredClone(pf.registration);pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{if(pfLookupFor()?.result?.ownerMatch===false)throw new Error('이 계정에서 올린 게시물이 아니에요. 게시한 계정을 다시 골라 주세요.');input.publishedAt=pfInstant(input.publishedAt);const formats=pfRegistrationFormats();if(formats.length>1&&!formats.includes(input.publicationFormat))throw new Error('실제로 올린 영상 형식을 골라 주세요.');if(!input.publicationFormat||!formats.includes(input.publicationFormat))delete input.publicationFormat;if(!input.publicationPackageId)delete input.publicationPackageId;const result=await api('/api/post-performance',input);if(!pfAlive(guard))return;pf.data.performance.entries=[result.entry,...pfEntries().filter(row=>row.id!==result.entry.id)];pf.registration=pfRegistration();pf.registrationAuto=null;pf.lookup=null;pf.lookupFill=null;if(pf.form==='register')pf.form='';const ep=pfEpisodes().find(row=>row.entries.some(entry=>entry.id===result.entry?.id));if(ep){pf.pick=ep.key;pf.target=null;}pfSetStatus(result.linked?'기존 게시 기록에 영상 형식을 연결했어요. 게시 시각과 모은 숫자는 그대로예요.':result.existing?'이미 기록한 게시물이에요. 그때의 게시 시각과 숫자를 불러왔어요.':'게시 기록을 저장했어요. 24·72시간 숫자를 자동으로 모아요.'+(result.publishedAtAdjusted?' 게시 시각은 플랫폼에 나온 시각으로 맞췄어요.':''));}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfSyncView();pfRender();pfLearningSchedule(0);}}}
async function pfCollect(id){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||entry?.canEdit===false||!entry)return;const guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfSetStatus('모을 시각과 계정 연결을 확인하고 있어요.');pfRender();try{const result=await api('/api/post-performance/'+encodeURIComponent(id)+'/collect',{});if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(pfAlive(guard))pfSetStatus('지금 수집 상태를 다시 읽었어요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('');}}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
async function pfSetActive(id){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||!entry||entry.canEdit===false)return;const guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{const result=await api('/api/post-performance/'+encodeURIComponent(id)+'/active',{active:entry.active===false});if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(pfAlive(guard))pfSetStatus(entry.active===false?'자동 수집을 다시 켰어요.':'자동 수집을 멈췄어요.');}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
function pfManual(key){return pf.manual[key]||(pf.manual[key]={metrics:{},measuredAt:'',note:''});}
async function pfSaveMetrics(id,hours){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||!entry||entry.canEdit===false)return;const key=id+':'+hours,draft=pf.manual[key],guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{if(!draft)throw new Error('본 숫자와 시각을 넣어 주세요.');const metrics={};for(const [name,value] of Object.entries(draft.metrics)){if(value==='')continue;const point=(entry.checkpoints||[]).find(row=>Number(row.hours)===Number(hours));if(point?.metrics?.[name]!==null&&point?.metrics?.[name]!==undefined)continue;const number=Number(value);if(!Number.isFinite(number)||number<0)throw new Error('숫자는 0 이상으로 넣어 주세요.');metrics[name]=number;}if(!Object.keys(metrics).length)throw new Error('본 숫자를 하나 이상 넣어 주세요.');const input={metrics,measuredAt:pfInstant(draft.measuredAt),note:draft.note},result=await api('/api/post-performance/'+encodeURIComponent(id)+'/checkpoints/'+hours,input);if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(!pfAlive(guard))return;delete pf.manual[key];pfSetStatus('본 숫자를 저장했어요. 본 시각이 같이 남아요.');}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
// 한 표에 채널 여럿의 빈칸이 있으면 숫자를 넣은 채널만 차례로 저장한다. 본 시각 · 어디서 봤나요는 표 아래 한 번만 넣는다.
async function pfSaveMetricsMany(form){const hours=Number(form.dataset.hours),ids=String(form.dataset.entries||form.dataset.entry||'').split(' ').filter(Boolean),measured=form.querySelector?.('[data-pf-measured]')?.value||'',note=form.querySelector?.('[data-pf-note]')?.value||'',filled=ids.filter(id=>Object.values(pf.manual[id+':'+hours]?.metrics||{}).some(value=>value!==''&&value!==null&&value!==undefined));if(!filled.length){pf.error='넣은 숫자가 없어요. 빈칸에 본 숫자를 넣고 저장해 주세요.';pfRender();return;}for(const id of filled){const draft=pfManual(id+':'+hours);draft.measuredAt=measured;draft.note=note;await pfSaveMetrics(id,hours);if(pf.error)break;}}
async function pfReadSubtitle(file){if(!file||pf.busy||!pfWritable())return;const guard=pfGuard(),request=++pf.subtitleRequest;try{if(file.size>200000||!/\.(srt|vtt)$/i.test(file.name))throw new Error('SRT·VTT 자막을 200KB 이하로 골라 주세요.');const text=await file.text();if(!pfAlive(guard)||request!==pf.subtitleRequest)return;pf.draft.subtitleText=text;pf.draft.subtitleFileName=file.name;pf.error='';}catch(error){if(pfAlive(guard)&&request===pf.subtitleRequest)pf.error=error.message;}finally{if(pfAlive(guard)&&request===pf.subtitleRequest)pfRender();}}

// ── 이벤트 ──
document.addEventListener('input',event=>{const target=event.target;if(!state.user)return;if(target.dataset?.pfSearch!==undefined&&target.matches?.('[data-pf-search]')){pf.search=target.value;pf.listLimit=PF_LIST_STEP;pfDetailRevive();pfListPaint();return;}if(pf.busy||!pfWritable())return;if(target.dataset.pfReviewField){if(pf.reviewBusy||!pf.reviewData?.canEdit)return;const draft=pfReviewDraft(target.dataset.check);if(draft&&['status','note'].includes(target.dataset.pfReviewField))draft[target.dataset.pfReviewField]=target.value;return;}const field=target.dataset.pfField,register=target.dataset.pfRegister;if(field&&['title','body','link','language','subtitleText'].includes(field)){pf.draft[field]=target.value;if(field==='subtitleText'&&!pf.draft.subtitleFileName)pf.draft.subtitleFileName=/^\s*WEBVTT/.test(target.value)?'subtitles.vtt':'subtitles.srt';if(field==='body'){const count=pfQuery('[data-pf-count="body"]');if(count)count.textContent=mtNum(target.value.length);}}if(register&&['channelId','url','publishedAt','title','publicationPackageId','publicationFormat'].includes(register))pf.registration[register]=target.value;if(target.dataset.pfMetric)pfManual(target.dataset.key).metrics[target.dataset.pfMetric]=target.value;if(target.dataset.pfMeasured)for(const key of target.dataset.pfMeasured.split(' ').filter(Boolean))pfManual(key).measuredAt=target.value;if(target.dataset.pfNote)for(const key of target.dataset.pfNote.split(' ').filter(Boolean))pfManual(key).note=target.value;});
document.addEventListener('change',event=>{const target=event.target;if(!state.user||pf.busy)return;if(target.dataset.pfReviewField){if(pf.reviewBusy||!pfWritable()||!pf.reviewData?.canEdit)return;const draft=pfReviewDraft(target.dataset.check);if(draft&&['status','note'].includes(target.dataset.pfReviewField))draft[target.dataset.pfReviewField]=target.value;return;}if(target.matches('[data-pf-source]')){void pfSelectProduction(target.value);return;}if(!pfWritable())return;if(target.matches('[data-pf-file]')){pf.file=target.files?.[0]||null;if(pf.file&&!pf.draft.title)pf.draft.title=pf.file.name.replace(/\.[^.]+$/,'');pfRender();}else if(target.matches('[data-pf-subtitle]'))void pfReadSubtitle(target.files?.[0]);else if(target.dataset.pfChannel){const selected=new Set(pf.draft.channels);if(target.checked)selected.add(target.dataset.pfChannel);else selected.delete(target.dataset.pfChannel);pf.draft.channels=[...selected];pfRender();}else if(['versionId','mode'].includes(target.dataset.pfField)){pf.draft[target.dataset.pfField]=target.value;if(target.dataset.pfField==='versionId')pfRender();}else if(['channelId','url','publishedAt','title','publicationPackageId','publicationFormat'].includes(target.dataset.pfRegister)){const field=target.dataset.pfRegister;pf.registration[field]=target.value;if(['channelId','publicationPackageId'].includes(field))pfSyncRegistrationFormat();if(['channelId','url'].includes(field)&&pfLookupAvailable()&&pf.registration.channelId&&String(pf.registration.url||'').trim()&&pf.lookup?.key!==pfLookupKey()){void pfLookup();return;}if(['channelId','url','publicationPackageId'].includes(field))pfRegisterPaint();}});
document.addEventListener('click',event=>{const target=event.target.closest?.('[data-pf-action]');if(!target||target.disabled||!state.user)return;const action=target.dataset.pfAction;
  // 보기만 바꾸는 동작은 저장 중에도 된다.
  if(action==='pick'){pfPick(target.dataset.key);return;}
  if(action==='pick-list'){pf.picking=!pf.picking;pfRenderKeep();return;}
  if(action==='filter'){pf.filter=target.dataset.filter==='all'?'all':'open';pf.meter='';pf.target=null;pf.listLimit=PF_LIST_STEP;pfSyncView();pfRenderKeep();return;}
  if(action==='meter'){const meter=['mine','collecting','recent','done'].includes(target.dataset.meter)?target.dataset.meter:'';pf.meter=pf.meter===meter?'':meter;pf.target=null;pf.listLimit=PF_LIST_STEP;pfSyncView();pfRenderKeep();return;}
  if(action==='clear-filter'){pf.meter='';pf.search='';pf.filter='open';pf.target=null;pfSyncView();pfRenderKeep();return;}
  if(action==='list-more'){pf.listLimit=(pf.listLimit||PF_LIST_STEP)+PF_LIST_STEP;pfRenderKeep();return;}
  if(action==='fill-all'){const key=target.dataset.key;if(key){pf.fillAll[key]=!pf.fillAll[key];pfRender();}return;}
  if(action==='sec'){pfOpenSec(target.dataset.sec);return;}
  if(action==='numbers'){const num=Number(target.dataset.hours)===72?'02':'01';pfOpenSec(num,`[data-pf-sec="${num}"] [data-pf-metric]`,`[data-pf-sec="${num}"] [data-pf-checkpoint]`);return;}
  if(action==='experiments'){pfOpenSec('05','[data-pf-learning]');return;}
  if(action==='form-close'){pfCloseForm();return;}
  if(action==='prepare'||action==='performance'){pf.form='';pfHonorView(action,true);pfRenderKeep();return;}
  if(action==='learning-more'||action==='entries-more'){pf.listLimit=(pf.listLimit||PF_LIST_STEP)+PF_LIST_STEP;pfRenderKeep();return;}
  if(pf.busy||pf.reviewBusy)return;
  if(action==='package-new'){pfOpenForm(target.dataset.inbox||'');return;}
  if(action==='register-new'){if(!pfWritable())return;pf.form='register';pf.picking=false;pf.target=null;pfSyncView();pfRender();pfFocusTarget('[data-pf-register="channelId"]');return;}
  if(action==='register-open'){const ep=pfCurrentEpisode();if(ep&&pfWritable()){pf.secOpen[ep.key+':03']=true;pfOpenSec('03','[data-pf-register="url"]');}return;}
  if(action==='lookup'){void pfLookup();return;}if(action==='link-check'){void pfLinkLoad(target.dataset.kind,target.dataset.id,true);return;}if(action==='review-open'){const ep=pfCurrentEpisode();if(ep)pf.secOpen[ep.key+':04']=true;if(!pfQuery('[data-pf-review-host="'+target.dataset.id+'"]'))pfRender();const sec=pfQuery('.maker-tools[data-mt="publication"] details[data-pf-sec="04"]');if(sec&&!sec.open)sec.open=true;void pfReviewOpen(target.dataset.id);return;}if(action==='review-refresh'){void pfReviewOpen(pf.reviewPackageId,false);return;}if(action==='review-close'){pfReviewClose();return;}if(action==='learning-plan'){void pfLearningPlan(target.dataset.entry,target.dataset.experiment);return;}if(action==='learning-refresh'){if(pf.learningFetching||pf.learningBusy)return;pfLearningStop(true);void pfLearningLoad(true);return;}if(action==='target-cancel'){pf.targetChoice=null;pfSetStatus('쓰던 내용을 그대로 뒀어요.');pfRender();}else if(action==='target-confirm'&&pf.targetChoice)void pfOpenTarget(pf.targetChoice,true);else if(action==='inbox-toggle')void pfInboxAction('toggle');else if(action==='inbox-scan')void pfInboxAction('scan');else if(action==='inbox-copy')void pfInboxCopy();else if(action==='inbox-use')void pfInboxUse(target.dataset.id);else if(action==='inbox-confirm')void pfInboxUse(target.dataset.id,true);else if(action==='inbox-cancel'){pf.inboxChoice='';pfInboxPaint();}else if(action==='refresh')void pfLoad();else if(action==='clear-subtitle'&&pfWritable()){pf.subtitleRequest++;pf.draft.subtitleText='';pf.draft.subtitleFileName='';pfRender();}else if(action==='use-package'&&pfWritable()){const row=pfPackages().find(row=>row.id===target.dataset.id);if(row)void pfOpenTarget({action:'publish',packageId:row.id});}else if(action==='collect')void pfCollect(target.dataset.id);else if(action==='active')void pfSetActive(target.dataset.id);});
document.addEventListener('submit',event=>{const form=event.target;if(!form.matches?.('[data-pf-form]'))return;event.preventDefault();if(!state.user||pf.busy)return;const kind=form.dataset.pfForm;if(kind==='upload')void pfUploadSelected();else if(kind==='package')void pfCreatePackage();else if(kind==='register')void pfRegisterPost();else if(kind==='metrics')void pfSaveMetricsMany(form);else if(kind==='review')void pfReviewSave(form.dataset.check);});
// 번호 구역(01~05)을 사람이 접고 펼친 것은 편마다 기억한다(다시 그려도 그대로).
document.addEventListener('toggle',event=>{const node=event.target;if(!node?.matches?.('details[data-pf-sec]'))return;const key=node.closest?.('[data-pf-detail]')?.dataset?.pfDetail;if(key)pf.secOpen[key+':'+node.dataset.pfSec]=node.open;},true);

document.addEventListener('visibilitychange',()=>{if(typeof state==='undefined')return;if(document.visibilityState==='hidden'){pfInboxStop();pfLearningStop(true);pfLinkStop(true);}else{pfInboxSchedule();pfLearningSchedule(0);pfLinkEnsure();}});
document.addEventListener('click',()=>queueMicrotask(()=>{pfInboxSchedule();pfLearningSchedule();pfLinkEnsure();}));
document.addEventListener('focusout',()=>queueMicrotask(()=>pfLearningPaint()));
document.addEventListener('selectionchange',()=>pfLearningPaint());
for(const type of ['pointerdown','wheel','touchstart','keydown'])document.addEventListener(type,pfReleaseFocusTarget,{capture:true,passive:true});
